/* MODULE tp02 · Bước 4 Tạo thông điệp · Cửa vào ngành hàng (category entry points)
   9 bài × 7 câu. Thương hiệu được nêu như ví dụ công khai; mọi con số là MINH HOẠ và tự khớp nhau. */
BAI_ADD({ mod:'tp02', lessons:[

/* ------------------------------------------------------------------ 01 */
{ id:'B:tp02-01', skill:'insight', read:'6 phút', t:'Khách nghĩ đến ngành hàng của bạn vào những lúc nào?',
  situation:'Bạn phụ trách một thương hiệu nước điện giải mới. Sếp hỏi: "Khách mua mình khi nào?" Cả phòng trả lời một câu: "Khi khát." Nhưng khát thì ai cũng uống nước lọc. Bạn cần một danh sách cụ thể hơn để viết quảng cáo, và chỉ có một buổi chiều để làm.',
  concept:{ name:'Liệt kê cửa vào theo năm câu hỏi',
    body:'Cửa vào ngành hàng là những tình huống khiến người ta chợt cần đến ngành hàng. Để liệt kê cho đủ, hỏi năm câu: <b>ai</b> đang cần (dân văn phòng, người chạy bộ, mẹ có con ốm), <b>khi nào</b> (sau khi tập, buổi trưa nắng, sáng sau tiệc), <b>ở đâu</b> (phòng gym, công trường, trên xe), <b>với ai</b> (một mình, cả đội bóng), và <b>cảm giác gì</b> (mệt lả, người nóng, sợ mất nước). Mỗi tổ hợp là một cửa vào. Hỏi về lần mua gần nhất và ghi bằng lời của khách, không bằng lời nhãn hàng. Khi vài cuộc phỏng vấn liên tiếp không thêm cửa vào mới, danh sách tạm đủ; lúc đó mới đếm mức phổ biến và xếp ưu tiên.' },
  example:'Nhóm bạn phỏng vấn nhanh 20 người đã mua nước điện giải trong tháng. Kết quả gom được 14 tình huống, ví dụ: "sau trận bóng tối thứ Tư", "sáng hôm sau đi nhậu", "con bị sốt, bác sĩ dặn bù nước", "làm ngoài trời giữa trưa". Không câu nào là "khi khát". Bốn tình huống đầu chiếm 13/20 người — đó là danh sách để bàn tiếp, không phải khẩu hiệu "giải khát tức thì".',
  takeaway:'Khách không mua "ngành hàng"; họ mua để giải quyết một lúc cụ thể trong ngày.',
  apply:'Chọn một sản phẩm quen. Trong 60 giây, nói ra năm cửa vào, mỗi cái trả lời đủ ai – khi nào – ở đâu.',
  mistakes:['Dừng ở một cửa vào chung chung như "khi khát", "khi đói".','Viết cửa vào bằng lợi ích sản phẩm thay vì bằng tình huống của khách.'],
  q:[
  { type:'mcq', stem:'Đoán trước: câu nào là một cửa vào ngành hàng đúng nghĩa cho nước điện giải?',
    options:[{k:'a',t:'Người tập gym muốn tăng cơ nhanh hơn trong ba tháng'},{k:'b',t:'Người ưu tiên sức khoẻ, chọn đồ uống ít đường và tự nhiên'},
             {k:'c',t:'Cả mùa hè, khi trời nóng và ai cũng thấy khát nước'},{k:'d',t:'Hết trận bóng tối thứ Tư, áo ướt đẫm, chưa muốn về ngay'}],
    answer:'d', why:{a:'Đây là mục tiêu dài hạn của một nhóm người, không phải một khoảnh khắc khiến họ chợt cần ngành hàng.',
      b:'Đây là giá trị sống của một phân khúc; cùng người đó có thể gặp rất nhiều khoảnh khắc khác nhau.',
      c:'Quá rộng, thực chất vẫn là "khi khát": không rõ ai, ở đâu, cảm giác gì nên không giúp viết quảng cáo.',
      d:'Đúng. Có khi nào, ai, cảm giác gì: một khoảnh khắc cụ thể khiến người ta cần đến ngành hàng.'} },
  { type:'mcq', stem:'Bạn chỉ có một buổi chiều để lập danh sách cửa vào cho nước điện giải. Bạn làm gì?',
    options:[{k:'a',t:'Họp nội bộ, mỗi người đề xuất một câu khẩu hiệu rồi bỏ phiếu chọn'},{k:'b',t:'Chép lại công dụng in trên nhãn và gom thành danh sách'},
             {k:'c',t:'Hỏi nhanh người vừa mua: lần gần nhất uống lúc nào, ở đâu, với ai'},{k:'d',t:'Tra từ khoá có lượng tìm kiếm cao nhất về nước điện giải trên mạng'}],
    answer:'c', why:{a:'Khẩu hiệu là bước sau; chưa biết tình huống thật thì bỏ phiếu chỉ ra ý thích của nội bộ.',
      b:'Nhãn nói về sản phẩm, không nói về khoảnh khắc của khách.',
      c:'Đúng. Hỏi về lần mua gần nhất cho tình huống cụ thể, bằng lời của khách, trong thời gian ngắn.',
      d:'Từ khoá có ích để bổ sung, nhưng thường là tên sản phẩm hoặc giá, ít khi mô tả trọn tình huống.'} },
  { type:'mcq', stem:'Trong năm câu hỏi ai / khi nào / ở đâu / với ai / cảm giác gì, câu "với ai" giúp phát hiện điều gì?',
    options:[{k:'a',t:'Người đi cùng có thể là người trả tiền hoặc gợi ý mua'},{k:'b',t:'Số lượng khách hàng mục tiêu cần nhắm trong chiến dịch'},
             {k:'c',t:'Mức giá mà khách hàng chấp nhận trả cho một chai'},{k:'d',t:'Kênh quảng cáo phù hợp nhất để chạy chiến dịch sắp tới của thương hiệu'}],
    answer:'a', why:{a:'Đúng. "Cả đội bóng" hay "mẹ mua cho con" cho thấy ai quyết định và cỡ lần mua.',
      b:'Quy mô khách là câu hỏi khác; "với ai" mô tả bối cảnh xã hội của lần dùng.',
      c:'Giá không lộ ra từ câu hỏi này.',
      d:'Kênh được chọn sau khi biết tình huống; câu hỏi này không trả lời trực tiếp.'} },
  { type:'mcq', stem:'Một cửa vào bị ghi là "Bổ sung khoáng nhanh". Cách viết lại nào đã thành tình huống thật của khách?',
    options:[{k:'a',t:'Người cần bổ sung khoáng nhanh sau khi vận động mạnh'},{k:'b',t:'Sáng thứ Bảy sau bữa nhậu, đầu nặng, chưa muốn ăn gì'},
             {k:'c',t:'Khách quan tâm sức khoẻ, ưu tiên thành phần tự nhiên'},{k:'d',t:'Bổ sung khoáng nhanh hơn nước lọc và nước ngọt thường'}],
    answer:'b', why:{a:'Chỉ đổi cách nói, vẫn là nhu cầu chung của sản phẩm; chưa có khi nào, ở đâu, cảm giác gì.',
      b:'Đúng. Có thời điểm, bối cảnh và cảm giác; khách nghe là nhận ra lúc của mình.',
      c:'Đây là mô tả một nhóm người, không phải một khoảnh khắc.',
      d:'Đây là so sánh lợi ích với đối thủ, vẫn đứng ở phía sản phẩm.'} },
  { type:'mcq', stem:'Đã phỏng vấn 20 người, ra 14 cửa vào; 5 cuộc cuối chỉ thêm đúng 1 cửa vào mới. Bạn làm gì tiếp?',
    options:[{k:'a',t:'Phỏng vấn thêm cho đủ 100 người để con số nhìn đủ tin cậy'},{k:'b',t:'Chọn cửa vào lạ nhất vì chưa đối thủ nào trong ngành nhắc tới nó'},
             {k:'c',t:'Gộp 14 cửa vào thành ba nhóm lớn để danh sách gọn và dễ nhớ'},{k:'d',t:'Dừng phỏng vấn, đếm mức phổ biến, chọn vài cửa vào để viết thử'}],
    answer:'d', why:{a:'Danh sách đã gần bão hoà; thêm người chỉ tốn công, trong khi chỉ có một buổi chiều.',
      b:'Lạ chưa có nghĩa là nhiều người gặp; chọn mà không đếm là đặt cược vào cái hiếm.',
      c:'Gộp thành nhóm lớn quay lại những cụm chung như "khi khát", mất đúng độ cụ thể đang cần.',
      d:'Đúng. Thêm phỏng vấn ít bổ sung nên đã đủ để xếp ưu tiên theo mức phổ biến và thử.'} },
  { type:'calc', stem:'Trong 13 người rơi vào bốn tình huống đầu, hai tình huống đứng đầu có 6 và 4 người. Nếu chỉ viết quảng cáo cho hai tình huống này, bao nhiêu phần trăm trong 20 người được phỏng vấn thấy tình huống của mình?',
    unit:'%', ans:50, tol:0.1, wrong:[[65,'SAI_TINH_TOAN'],[76.9,'SAI_MAU_SO']], errors:['SAI_TINH_TOAN','SAI_MAU_SO'],
    steps:['Hai tình huống đầu: 6 + 4 = 10 người.','Tỉ lệ so với toàn bộ 20 người được hỏi: 10 ÷ 20 = <b>50%</b>.','Mẫu số là 20 người đã phỏng vấn, không phải 13 người đã rơi vào bốn tình huống.'] },
  { type:'mcq', stem:'Một quán cà phê liệt kê cửa vào: "họp khách gần văn phòng", "ngồi làm việc cả buổi", "hẹn hò tối cuối tuần". Câu hỏi nào trong năm câu đang tạo khác biệt chính giữa ba cửa vào này?',
    options:[{k:'a',t:'Cảm giác gì, vì ba cửa vào đều cùng một cảm xúc'},{k:'b',t:'Với ai: đi cùng khách, ngồi một mình hay với người yêu'},
             {k:'c',t:'Ở đâu, vì cả ba đều ở cùng một quán'},{k:'d',t:'Ai, vì chỉ có một nhóm khách hàng là dân văn phòng trẻ tuổi'}],
    answer:'b', why:{a:'Cảm xúc ba cửa vào khác nhau, nhưng nó không phải trục chính ở đây.',
      b:'Đúng. Đi cùng khách, ngồi một mình hay hẹn hò — mỗi kiểu đi cùng đòi một không gian khác.',
      c:'Cùng quán không có nghĩa "ở đâu" là trục tạo khác biệt.',
      d:'Cùng một người có thể rơi vào cả ba cửa vào.'} } ] },

/* ------------------------------------------------------------------ 02 */
{ id:'B:tp02-02', skill:'brand', read:'7 phút', t:'Có 14 cửa vào, nên chiếm cửa vào nào trước?',
  situation:'Danh sách cửa vào của nước điện giải có 14 dòng. Ngân sách năm chỉ đủ nói rõ về hai hoặc ba tình huống. Nhóm sáng tạo muốn chọn "sau buổi tập gym" vì hình ảnh đẹp. Bạn cần một cách chọn có căn cứ hơn là hình ảnh đẹp.',
  concept:{ name:'Chấm điểm cửa vào: độ lớn × độ phù hợp × độ trống',
    body:'Mỗi cửa vào được chấm ba thứ. <b>Độ lớn</b>: bao nhiêu người, bao nhiêu lần một tháng rơi vào tình huống đó. <b>Độ phù hợp</b>: sản phẩm của bạn giải quyết tình huống đó tốt đến đâu so với lựa chọn khác. <b>Độ trống</b>: đối thủ đã gắn chặt với cửa vào đó chưa. Cửa vào đáng chiếm là cửa vào đủ lớn, sản phẩm thật sự hợp, và chưa bị ai giữ. Hình ảnh đẹp là chuyện của khâu sáng tạo, không phải tiêu chí chọn. Lưu ý: cửa vào (category entry points) là khái niệm của Jenni Romaniuk (Ehrenberg-Bass); theo quan điểm này hiếm hãng nào độc quyền một cửa vào — nhiều hãng cùng gắn với một tình huống — nên "trống" nghĩa là đối thủ gắn còn yếu. Quan điểm định vị của Ries & Trout thì nhấn mạnh chiếm một chỗ riêng.' },
  example:'Chấm thang 1–5: "sau gym" lớn 2, phù hợp 5, trống 1 (hai hãng đã chiếm) → tích 10. "Làm ngoài trời giữa trưa" lớn 4, phù hợp 4, trống 4 → 64. "Sáng sau tiệc" lớn 3, phù hợp 4, trống 3 → 36. Dù "sau gym" hình ảnh đẹp nhất, nó xếp cuối. Bạn đề xuất dồn ngân sách vào "làm ngoài trời giữa trưa", giữ "sáng sau tiệc" làm cửa vào phụ.',
  takeaway:'Chọn cửa vào theo độ lớn, độ phù hợp và độ trống — không theo độ đẹp của cảnh quay.',
  apply:'Lấy ba cửa vào của một sản phẩm quen, chấm ba tiêu chí thang 1–5, rồi nói trong 60 giây cửa vào nào thắng và vì sao.',
  mistakes:['Chọn cửa vào theo sở thích của nhóm sáng tạo.','Rải ngân sách đều cho mọi cửa vào nên không cửa nào gắn được thương hiệu.'],
  q:[
  { type:'mcq', stem:'Đoán trước: điều gì quan trọng nhất khi chọn cửa vào để chiếm?',
    options:[{k:'a',t:'Cửa vào cho ra cảnh quay quảng cáo đẹp và dễ lan truyền nhất'},{k:'b',t:'Cửa vào mà đối thủ lớn nhất đang đầu tư nhiều nhất'},
             {k:'c',t:'Cửa vào đủ lớn, sản phẩm hợp và chưa có ai giữ chặt'},{k:'d',t:'Cửa vào mà sếp và đội ngũ yêu thích'}],
    answer:'c', why:{a:'Cảnh đẹp giúp quảng cáo, nhưng không nói gì về độ lớn hay đối thủ.',
      b:'Đi theo đối thủ lớn là tranh chỗ đã có người giữ, tốn kém nhất.',
      c:'Đúng. Ba tiêu chí cùng lúc cho biết cửa vào nào đáng tiền.',
      d:'Sở thích nội bộ không phản ánh khách hàng.'} },
  { type:'mcq', stem:'Nhóm sáng tạo vẫn muốn làm "sau buổi tập gym" (điểm 10) thay vì "làm ngoài trời giữa trưa" (điểm 64). Bạn chọn làm gì?',
    options:[{k:'a',t:'Làm theo nhóm sáng tạo vì họ hiểu hình ảnh nhất'},{k:'b',t:'Chia đôi ngân sách cho cả hai để không ai phật lòng'},
             {k:'c',t:'Chọn "làm ngoài trời giữa trưa" và nhờ nhóm sáng tạo tìm cách quay nó thật hay'},{k:'d',t:'Hoãn quyết định để chạy thử cả 14 cửa vào rồi đo xem cái nào tốt nhất'}],
    answer:'c', why:{a:'Hình ảnh là khâu thể hiện; cửa vào là khâu chiến lược.',
      b:'Chia đôi khiến cả hai đều mỏng, không cửa nào gắn chặt thương hiệu.',
      c:'Đúng. Giữ lựa chọn có căn cứ, giao bài toán sáng tạo cho đúng người.',
      d:'Chạy 14 cửa vào với ngân sách cho hai ba cái thì mỗi cái quá mỏng để đo được gì.'} },
  { type:'calc', stem:'Cửa vào "sáng sau tiệc" được chấm: độ lớn 3, độ phù hợp 4, độ trống 3. Tích điểm là bao nhiêu?',
    unit:'điểm', ans:36, tol:0, wrong:[[10,'SAI_TINH_TOAN'],[12,'SAI_TINH_TOAN']], errors:['SAI_TINH_TOAN'],
    steps:['Tích điểm = độ lớn × độ phù hợp × độ trống.','3 × 4 × 3 = <b>36</b>.'] },
  { type:'mcq', stem:'Vì sao dùng phép nhân ba điểm thay vì cộng?',
    options:[{k:'a',t:'Nhân cho số to hơn nên dễ trình bày hơn trong buổi họp'},{k:'b',t:'Một tiêu chí rất thấp sẽ kéo cả cửa vào xuống, đúng với thực tế'},
             {k:'c',t:'Phép cộng không dùng được cho thang điểm từ 1 đến 5'},{k:'d',t:'Phép nhân giúp ưu tiên độ lớn của cửa vào hơn hai tiêu chí còn lại'}],
    answer:'b', why:{a:'Số to không làm quyết định tốt hơn.',
      b:'Đúng. Cửa vào lớn mà sản phẩm không hợp, hay đã bị đối thủ khoá chặt, thì gần như vô giá trị.',
      c:'Cộng vẫn tính được, chỉ là không phạt điểm yếu chí mạng.',
      d:'Phép nhân coi ba tiêu chí ngang nhau.'} },
  { type:'mcq', stem:'Một hãng dầu gội thấy cửa vào "gội sau khi bơi" rất trống và sản phẩm rất hợp, nhưng chỉ khoảng 2% người dùng đi bơi hằng tuần. Kết luận nào hợp lý?',
    options:[{k:'a',t:'Chiếm ngay vì đây là cửa vào trống và phù hợp nhất danh sách'},{k:'b',t:'Bỏ hẳn vì cửa vào 2% quá nhỏ, không đáng giữ'},
             {k:'c',t:'Có thể giữ làm cửa vào phụ, không đủ lớn để làm trục chính'},{k:'d',t:'Đổi công thức sản phẩm để hợp với cửa vào lớn nhất của đối thủ'}],
    answer:'c', why:{a:'Trống và hợp nhưng quá nhỏ thì không nuôi nổi tăng trưởng.',
      b:'Cửa vào nhỏ vẫn có vai trò phụ, rẻ để giữ.',
      c:'Đúng. Độ lớn thấp khiến nó chỉ đáng làm vai phụ.',
      d:'Đổi sản phẩm để tranh cửa vào đã bị giữ là quyết định đắt nhất.'} },
  { type:'mcq', stem:'Cách tốt nhất để biết một cửa vào đã bị đối thủ "giữ chặt" là gì?',
    options:[{k:'a',t:'Hỏi khách: khi ở tình huống đó, thương hiệu nào hiện ra trong đầu'},{k:'b',t:'Xem đối thủ có đăng bài mạng xã hội về tình huống đó không'},
             {k:'c',t:'Đoán theo quy mô doanh thu của đối thủ trong ngành hàng'},{k:'d',t:'Đếm số từ khoá mà đối thủ đang mua quảng cáo tìm kiếm trên Google'}],
    answer:'a', why:{a:'Đúng. Giữ chặt là chuyện trong trí nhớ khách, nên phải đo ở khách.',
      b:'Đăng bài không có nghĩa khách đã gắn đối thủ với tình huống.',
      c:'Hãng lớn chưa chắc giữ mọi cửa vào.',
      d:'Mua từ khoá cho thấy ý định của đối thủ, không phải trí nhớ của khách.'} },
  { type:'mcq', stem:'Sau khi chấm, ba cửa vào đứng đầu có điểm 64, 60 và 58. Ngân sách chỉ đủ cho một cửa vào chính. Bạn cân nhắc thêm điều gì?',
    options:[{k:'a',t:'Chọn cửa vào 64 điểm, vì bảng điểm đã xếp nó đứng đầu'},{k:'b',t:'Chia đều cho cả ba vì điểm gần như bằng nhau'},
             {k:'c',t:'Bỏ cả ba và chấm lại từ đầu vì không có cửa vào nào vượt trội rõ ràng'},{k:'d',t:'Điểm sát nhau thì xét cửa nào có thể gắn lâu dài, ít tốn tiền giữ'}],
    answer:'d', why:{a:'Chênh 4–6 điểm nằm trong sai số của việc chấm bằng cảm nhận.',
      b:'Chia đều quay lại lỗi rải mỏng.',
      c:'Điểm sát nhau là tin tốt: có nhiều lựa chọn tốt, không phải không có lựa chọn.',
      d:'Đúng. Khi điểm sát, tiêu chí phụ như độ bền và chi phí giữ quyết định.'} } ] },

/* ------------------------------------------------------------------ 03 */
{ id:'B:tp02-03', skill:'brand', read:'7 phút', t:'Cửa vào lớn nhưng đông đối thủ, hay cửa vào nhỏ còn bỏ trống?',
  situation:'Một thương hiệu mì ly nhỏ đang phân vân. Cửa vào "bữa khuya khi làm việc muộn" rất lớn, nhưng ba hãng lớn đều nói về nó. Cửa vào "ăn nhanh giữa ca trực bệnh viện" nhỏ hơn nhiều, gần như chưa ai nói. Ngân sách quảng cáo năm là 3 tỉ, chỉ bằng một phần mười hãng dẫn đầu.',
  concept:{ name:'Tỉ lệ tiếng nói trong cửa vào',
    body:'Ở một cửa vào đông đối thủ, thương hiệu nhỏ chỉ có một phần rất bé tiếng nói, nên khó gắn tên mình vào tình huống. Ở cửa vào nhỏ bỏ trống, cùng số tiền cho bạn gần như toàn bộ tiếng nói. Hãy ước tính: trong mỗi cửa vào, ngân sách của bạn chiếm bao nhiêu phần tổng chi tiêu của mọi hãng. Thương hiệu nhỏ thường nên thắng một cửa vào nhỏ trước, rồi dùng nó làm bàn đạp — thay vì làm người thứ tư thì thầm trong một căn phòng ồn ào.' },
  example:'Ước tính chi tiêu nói về "bữa khuya" của cả ngành khoảng 40 tỉ; nếu dồn hết 3 tỉ vào, mì ly nhỏ chiếm 3/43 ≈ 7% tiếng nói. Với "giữa ca trực", đối thủ gần như không chi; dành 1 tỉ cho nó là gần như toàn bộ tiếng nói. Nhóm chọn "giữa ca trực" làm trục, quay cảnh y tá ăn vội lúc 2 giờ sáng, rồi mở rộng sang "ca đêm" nói chung — công nhân, bảo vệ, tài xế.',
  takeaway:'Thương hiệu nhỏ thắng bằng cách làm to tiếng nhất trong một phòng nhỏ, rồi mới mở cửa sang phòng lớn.',
  apply:'Chọn một thương hiệu nhỏ bạn biết. Trong 60 giây, nêu một cửa vào nhỏ nó có thể thống trị và cửa vào lớn hơn kế bên để mở rộng sau.',
  mistakes:['Tưởng cửa vào lớn nhất luôn là lựa chọn tốt nhất.','Chọn cửa vào nhỏ nhưng không có kế hoạch mở rộng sang cửa vào kế bên.'],
  q:[
  { type:'mcq', stem:'Đoán trước: với ngân sách bằng 1/10 hãng dẫn đầu, thương hiệu nhỏ nên nhắm cửa vào nào?',
    options:[{k:'a',t:'Cửa vào lớn nhất, vì đó là nơi nhiều khách nhất'},{k:'b',t:'Nhiều cửa vào cùng lúc, để không bỏ sót khách nào'},
             {k:'c',t:'Cửa vào đông nhất nhưng làm quảng cáo gây sốc để nổi bật'},{k:'d',t:'Một cửa vào nhỏ còn trống, nơi tiền của mình đủ để át tiếng'}],
    answer:'d', why:{a:'Đông khách nhưng cũng đông tiếng nói; phần của bạn quá nhỏ để được nhớ.',
      b:'Rải ra nhiều nơi thì không nơi nào gắn được tên.',
      c:'Sốc có thể được chú ý một lần, nhưng khó gắn bền với tình huống khi đối thủ chi gấp mười.',
      d:'Đúng. Cùng số tiền nhưng chiếm gần trọn tiếng nói trong tình huống đó.'} },
  { type:'mcq', stem:'Bạn đã chọn "giữa ca trực bệnh viện". Sau một năm, khảo sát cho thấy thương hiệu đã gắn chặt với cửa vào này. Bạn làm gì tiếp?',
    options:[{k:'a',t:'Mở sang cửa vào kế bên có chung khoảnh khắc: các nghề làm ca đêm'},{k:'b',t:'Chuyển thẳng sang "bữa khuya khi làm việc muộn" với cả ngân sách'},
             {k:'c',t:'Giữ nguyên, vì đã thắng thì không nên thay đổi gì'},{k:'d',t:'Cắt quảng cáo vì khách đã nhớ, tiết kiệm tiền cho năm sau'}],
    answer:'a', why:{a:'Đúng. Mở sang cửa vào gần nhau về khoảnh khắc giúp tận dụng những gì đã gắn được.',
      b:'Nhảy thẳng vào phòng đông nhất là quay lại bài toán 7% tiếng nói.',
      c:'Đứng yên thì tăng trưởng bị trần bởi độ lớn của cửa vào nhỏ.',
      d:'Trí nhớ phai dần; cắt hẳn là để đối thủ lấp chỗ.'} },
  { type:'calc', stem:'Cả ngành chi 40 tỉ để nói về cửa vào "bữa khuya". Nếu mì ly nhỏ chi thêm 3 tỉ vào đó, thương hiệu chiếm bao nhiêu phần trăm tổng tiếng nói? (làm tròn 1 chữ số thập phân)',
    unit:'%', ans:7, tol:0.1, wrong:[[7.5,'SAI_MAU_SO']], errors:['SAI_MAU_SO'],
    steps:['Tổng chi sau khi mì ly nhỏ tham gia = 40 + 3 = 43 tỉ.','Tỉ lệ tiếng nói = 3 ÷ 43 ≈ 0,0698 ≈ <b>7,0%</b>.'] },
  { type:'mcq', stem:'Một cửa vào "trống" có thể trống vì những lý do khác nhau. Lý do nào nên khiến bạn ngừng lại?',
    options:[{k:'a',t:'Đối thủ lớn chưa để ý đến tình huống này'},{k:'b',t:'Tình huống mới xuất hiện gần đây do thói quen làm việc thay đổi'},
             {k:'c',t:'Rất ít người thật sự rơi vào tình huống đó trong một tháng'},{k:'d',t:'Các hãng lớn đang bận tranh nhau ở những cửa vào đông khách hơn nhiều'}],
    answer:'c', why:{a:'Đối thủ chưa để ý chính là cơ hội.',
      b:'Tình huống mới nổi là cơ hội vào sớm.',
      c:'Đúng. Trống vì quá nhỏ thì thắng cũng chẳng được bao nhiêu.',
      d:'Đối thủ bận nơi khác là lý do tốt để vào.'} },
  { type:'mcq', stem:'Một ví điện tử mới thấy cửa vào "trả tiền mua sắm online" có mọi ví lớn chen nhau, còn "chia tiền ăn nhóm bạn" ít ai nói. Lựa chọn nào hợp logic bài học?',
    options:[{k:'a',t:'Dồn tiền vào mua sắm online vì giá trị giao dịch lớn hơn'},{k:'b',t:'Chiếm "chia tiền ăn nhóm", rồi mở sang các lần tiêu chung khác'},
             {k:'c',t:'Làm cả hai với ngân sách chia đôi để thử'},{k:'d',t:'Tăng mức hoàn tiền mua sắm online lên cao hơn các ví đầu ngành'}],
    answer:'b', why:{a:'Giao dịch lớn nhưng tiếng nói của ví mới gần như bằng không ở đó.',
      b:'Đúng. Một khoảnh khắc chưa ai giữ, lại dễ lan vì có nhiều người cùng dùng.',
      c:'Chia đôi làm cả hai mỏng.',
      d:'Đua hoàn tiền là cuộc chơi của túi tiền lớn và không gắn được tình huống riêng.'} },
  { type:'mcq', stem:'Vì sao cửa vào nhỏ được chọn nên "kề" với một cửa vào lớn hơn?',
    options:[{k:'a',t:'Để quảng cáo có thể dùng lại cùng một bộ phim cho cả hai cửa vào'},{k:'b',t:'Để cơ quan quản lý không cho là quảng cáo nhắm quá hẹp'},
             {k:'c',t:'Để có sẵn đường mở rộng mà không phải xây lại trí nhớ từ đầu'},{k:'d',t:'Để giá bán có thể tăng lên khi đổi cửa vào'}],
    answer:'c', why:{a:'Dùng lại phim là phụ; lý do chính là trí nhớ đã có.',
      b:'Không có liên quan đến quy định.',
      c:'Đúng. Tình huống gần nhau chia sẻ hình ảnh và cảm giác, nên mở rộng rẻ hơn.',
      d:'Giá không phải lý do chọn cửa vào kề.'} },
  { type:'mcq', stem:'Một nhãn trà nói: "Chúng tôi nhỏ, nên sẽ nói về mọi dịp để ai cũng thấy mình hợp." Sai ở đâu?',
    options:[{k:'a',t:'Nhãn nhỏ không nên quảng cáo, chỉ nên dựa vào truyền miệng'},{k:'b',t:'Nói về nhiều dịp là đúng hướng, chỉ việc tăng tần suất đăng'},
             {k:'c',t:'Nên nói về giá rẻ thay vì nói về dịp dùng'},{k:'d',t:'Tiền ít rải các dịp thì không dịp nào đủ đậm để khách nhớ tên'}],
    answer:'d', why:{a:'Quảng cáo vẫn cần; vấn đề là nói về quá nhiều thứ.',
      b:'Tăng tần suất với ngân sách nhỏ vẫn bị chia mỏng ra nhiều dịp.',
      c:'Nói giá rẻ không giúp khách nhớ đến mình đúng lúc cần.',
      d:'Đúng. Tập trung là cách duy nhất để tiền ít tạo được dấu ấn.'} } ] },

/* ------------------------------------------------------------------ 04 */
{ id:'B:tp02-04', skill:'creative', read:'7 phút', t:'Làm sao để quảng cáo gắn tên thương hiệu vào đúng một tình huống?',
  situation:'Bạn nhận bản nháp kịch bản ngắn cho nước điện giải: một người chạy bộ, cảnh đẹp, câu chốt "Bù nước chuẩn khoa học". Cửa vào đã chọn là "làm ngoài trời giữa trưa". Bạn cần sửa để khán giả nhớ: lần tới đứng giữa trời nắng, tên thương hiệu hiện ra.',
  concept:{ name:'Công thức gắn: tình huống nhận ra được + thương hiệu sớm + lặp lại',
    body:'Để một tình huống gợi ra thương hiệu, quảng cáo phải làm ba việc. Một, dựng <b>tình huống mà khán giả nhận ra ngay là của mình</b> — chi tiết cụ thể như mũ bảo hiểm, cái nắng đổ lửa, đồng hồ chỉ giữa trưa. Hai, cho <b>thương hiệu xuất hiện sớm và ngay trong tình huống</b>, không đợi đến giây cuối. Ba, <b>nói lại cùng một cặp tình huống – thương hiệu</b> qua nhiều đợt, nhiều kênh. Mỗi lần lặp là một lần củng cố đường nối trong trí nhớ.' },
  example:'Kịch bản sửa: mở đầu, thợ lắp máy lạnh leo mái tôn giữa trưa, đồng hồ vừa qua mười hai giờ. Ngay sau đó, chai nước với logo rõ nằm trong túi đồ nghề. Cuối phim, câu chốt: "Giữa trưa nắng, có [tên]." Cảnh chạy bộ bị bỏ. Cùng câu này được dùng trên biển quảng cáo gần công trường và bài đăng mạng xã hội lúc gần trưa.',
  takeaway:'Quảng cáo phải cho thấy tình huống trước, thương hiệu ngay trong đó, và lặp lại cặp ấy cho đến khi nó thành phản xạ.',
  apply:'Viết lại câu chốt một quảng cáo bạn nhớ sao cho nó nêu tình huống và tên thương hiệu trong cùng một câu, đọc to trong 60 giây.',
  mistakes:['Để thương hiệu hiện ra ở giây cuối khi khán giả đã lướt đi.','Mỗi đợt quảng cáo đổi một tình huống mới nên không cặp nào được củng cố.'],
  q:[
  { type:'mcq', stem:'Đoán trước: trong một phim ngắn, logo nên xuất hiện lúc nào để gắn với tình huống tốt nhất?',
    options:[{k:'a',t:'Chỉ ở giây cuối để tạo bất ngờ'},{k:'b',t:'Sớm và ngay trong tình huống, lặp lại ở cuối'},
             {k:'c',t:'Không cần logo, màu thương hiệu là đủ để nhớ'},{k:'d',t:'Ở giữa phim, khi cảm xúc của khán giả lên cao nhất và tập trung nhất'}],
    answer:'b', why:{a:'Thương hiệu chỉ hiện ở giây cuối thì người đã lướt đi sẽ không thấy; bất ngờ không tạo được đường nối.',
      b:'Đúng. Thương hiệu phải nằm trong tình huống để hai thứ được nhớ cùng nhau.',
      c:'Màu sắc giúp nhận diện, nhưng với thương hiệu mới thì chưa đủ.',
      d:'Chỉ ở giữa vẫn chưa gắn chặt; cần xuất hiện sớm và lặp.'} },
  { type:'mcq', stem:'Kịch bản nháp có cảnh chạy bộ đẹp nhưng cửa vào là "làm ngoài trời giữa trưa". Bạn sửa gì trước tiên?',
    options:[{k:'a',t:'Giữ cảnh chạy bộ, thêm dòng chữ "cả khi làm việc ngoài trời"'},{k:'b',t:'Đổi câu chốt sang lời khen về thành phần khoáng chất'},
             {k:'c',t:'Thay bằng cảnh người lao động giữa trưa nắng, chi tiết dễ nhận ra'},{k:'d',t:'Tăng độ dài phim gấp đôi để kể được cả hai tình huống cùng lúc'}],
    answer:'c', why:{a:'Hình ảnh mạnh hơn chữ; khán giả sẽ nhớ cảnh chạy bộ.',
      b:'Thành phần là lợi ích, không dựng được tình huống.',
      c:'Đúng. Tình huống phải hiện ra trên màn hình để khán giả nhận ra là của mình.',
      d:'Hai tình huống trong một phim làm loãng cả hai đường nối.'} },
  { type:'mcq', stem:'Câu chốt nào gắn thương hiệu vào cửa vào rõ nhất?',
    options:[{k:'a',t:'"Giữa trưa nắng, có [tên]"'},{k:'b',t:'"[Tên] — bù nước siêu tốc"'},
             {k:'c',t:'"Sảng khoái tức thì, tràn đầy năng lượng"'},{k:'d',t:'"Thương hiệu điện giải số một được yêu thích nhất năm nay"'}],
    answer:'a', why:{a:'Đúng. Tình huống và tên nằm cùng một câu ngắn.',
      b:'Có tên và lợi ích nhưng không có tình huống nào để gắn vào.',
      c:'Chỉ có lợi ích, không có tên, không có tình huống.',
      d:'Lời khẳng định vị thế, không gắn với khoảnh khắc nào.'} },
  { type:'mcq', stem:'Vì sao phải lặp lại cùng một cặp tình huống – thương hiệu qua nhiều đợt?',
    options:[{k:'a',t:'Để tiết kiệm chi phí sản xuất phim quảng cáo mới mỗi năm'},{k:'b',t:'Vì quy định yêu cầu thông điệp nhất quán qua các kênh'},
             {k:'c',t:'Vì đường nối trong trí nhớ mạnh lên sau mỗi lần gặp lại'},{k:'d',t:'Vì khán giả thích xem đi xem lại cùng một quảng cáo'}],
    answer:'c', why:{a:'Tiết kiệm là lợi ích phụ, không phải lý do.',
      b:'Không có quy định như vậy; đây là chuyện trí nhớ.',
      c:'Đúng. Mỗi lần lặp củng cố thêm liên kết giữa tình huống và tên.',
      d:'Khán giả thường chán; có thể đổi cách thể hiện nhưng giữ cặp tình huống – thương hiệu.'} },
  { type:'mcq', stem:'Một hãng kẹo cao su đổi tình huống mỗi quý: sau ăn, trước hẹn hò, khi lái xe, lúc học bài. Hệ quả dễ gặp nhất là gì?',
    options:[{k:'a',t:'Khách nhớ hãng ở cả bốn tình huống nhờ độ phủ rộng'},{k:'b',t:'Không tình huống nào đủ đợt lặp để gợi ra tên hãng'},
             {k:'c',t:'Doanh số tăng đều bốn quý vì mỗi quý có một thông điệp mới'},{k:'d',t:'Chi phí sản xuất giảm vì mỗi phim chỉ một bối cảnh'}],
    answer:'b', why:{a:'Mỗi tình huống chỉ được nói một quý rồi bỏ, không đủ để thành phản xạ.',
      b:'Đúng. Đổi liên tục nghĩa là không cặp nào được củng cố.',
      c:'Thông điệp mới không tự tạo doanh số nếu không ai nhớ.',
      d:'Chi phí sản xuất không phải vấn đề ở đây.'} },
  { type:'mcq', stem:'Ngoài phim, cách nào giúp củng cố cặp "giữa trưa nắng – [tên]" ở ngoài đời?',
    options:[{k:'a',t:'Đặt biển quảng cáo gần công trường, đăng bài lúc gần trưa'},{k:'b',t:'Tài trợ một giải chạy bộ vào sáng sớm cuối tuần'},
             {k:'c',t:'In mã giảm giá lên nắp chai, dùng được cả năm'},{k:'d',t:'Mời người nổi tiếng quay video review sản phẩm trong phòng thu có máy lạnh mát mẻ'}],
    answer:'a', why:{a:'Đúng. Gặp thương hiệu ngay trong hoặc gần tình huống thật là cách gắn mạnh nhất.',
      b:'Sáng sớm, chạy bộ — lệch hẳn cửa vào đã chọn.',
      c:'Mã giảm giá kích mua nhưng không gắn với tình huống nào.',
      d:'Phòng máy lạnh là tình huống ngược lại.'} },
  { type:'mcq', stem:'Một hãng bột giặt quay cảnh "áo đồng phục dính mực của con trước giờ đến trường". Điều gì làm cảnh này mạnh?',
    options:[{k:'a',t:'Có trẻ em nên dễ gây thiện cảm với khán giả'},{k:'b',t:'Cảnh có nhiều màu sắc nên dễ nổi trên mạng xã hội'},
             {k:'c',t:'Nó chứng minh rằng sản phẩm giặt sạch được vết bẩn khó, kể cả mực bút bi'},{k:'d',t:'Chi tiết cụ thể khiến cha mẹ nhận ra ngay khoảnh khắc buổi sáng của mình'}],
    answer:'d', why:{a:'Thiện cảm có, nhưng sức mạnh nằm ở độ nhận ra tình huống.',
      b:'Màu sắc là phụ.',
      c:'Đó là lợi ích; cảnh mạnh vì nó dựng đúng khoảnh khắc.',
      d:'Đúng. Chi tiết cụ thể làm tình huống thành "của mình", nên lần sau gặp lại sẽ gợi ra tên.'} } ] },

/* ------------------------------------------------------------------ 05 */
{ id:'B:tp02-05', skill:'comm', read:'6 phút', t:'Mùa Tết và mùa thi: có nên chạy theo cửa vào theo mùa?',
  situation:'Một hãng hạt dinh dưỡng đóng hộp bán đều quanh năm, doanh số tháng khoảng 2 tỉ. Mùa Tết mọi hãng đồ ăn đều đổ tiền quảng cáo quà biếu. Mùa thi tháng 6 thì ít ai nói. Bạn có 1,2 tỉ ngân sách mùa vụ và phải chọn.',
  concept:{ name:'Cửa vào theo mùa: đỉnh ngắn, cạnh tranh đậm',
    body:'Có những cửa vào chỉ mở vài tuần mỗi năm: Tết, Trung thu, mùa thi, mùa tựu trường. Chúng có hai điểm đặc biệt. Nhu cầu dồn vào một khoảng ngắn nên dễ thấy doanh số nhảy vọt. Nhưng mọi hãng cùng biết lịch, nên cửa vào lớn như Tết thường cực đông tiếng nói. Cách chọn: xem mùa nào sản phẩm của bạn có lý do thật để có mặt, và mùa nào bạn đủ tiếng nói để không bị chìm. Chiếm được một mùa, lặp lại nhiều năm, thương hiệu thành một phần của lịch trong đầu khách. Khi đo, so với cùng kỳ năm trước và tính trên lãi gộp, vì mùa vụ vốn đã làm doanh số nhích lên.' },
  example:'Tết: ngành đồ ăn chi rất lớn, hộp hạt chỉ là một lựa chọn quà giữa hàng trăm. Mùa thi: phụ huynh lo con ăn gì cho tỉnh táo, ít đối thủ nói. Hãng dồn 1,2 tỉ vào 5 tuần trước kỳ thi với thông điệp "Mùa ôn thi, hộp hạt trên bàn học". Tháng 6 năm trước, không chạy gì, doanh số 2 tỉ; năm nay lên 2,9 tỉ, tăng 0,9 tỉ doanh thu. Với biên gộp 40% đó chỉ là 0,36 tỉ lãi gộp, năm đầu lỗ khoảng 0,84 tỉ. Năm hai rẻ hơn mới là giả định cần đo, nên đặt ngưỡng dừng trước khi chi tiếp.',
  takeaway:'Mùa vụ nào cũng có cửa vào; chọn mùa bạn có lý do thật để có mặt và đủ tiếng để được nghe.',
  apply:'Chọn một sản phẩm, liệt kê ba mùa trong năm nó có thể gắn vào, rồi nói trong 60 giây mùa nào đáng chiếm nhất.',
  mistakes:['Mặc định dồn hết vào Tết chỉ vì ai cũng làm vậy.','Chiếm một mùa rồi năm sau bỏ, khiến công gắn năm trước mất đi.'],
  q:[
  { type:'mcq', stem:'Đoán trước: vì sao cửa vào Tết thường khó thắng với thương hiệu vừa và nhỏ?',
    options:[{k:'a',t:'Vì người Việt ít mua sắm vào dịp Tết'},{k:'b',t:'Vì quảng cáo Tết bị giới hạn thời lượng trên truyền hình'},
             {k:'c',t:'Vì hầu hết các hãng cùng dồn tiền vào đúng mấy tuần đó'},{k:'d',t:'Vì khách dịp Tết chỉ mua hàng nhập khẩu, không mua hàng trong nước'}],
    answer:'c', why:{a:'Ngược lại, Tết là mùa mua sắm lớn.',
      b:'Vấn đề không phải thời lượng mà là số hãng cùng nói.',
      c:'Đúng. Cửa vào lớn và ai cũng biết lịch nên cực đông tiếng nói.',
      d:'Khách vẫn mua hàng trong nước rất nhiều.'} },
  { type:'mcq', stem:'Bạn có 1,2 tỉ ngân sách mùa vụ cho hộp hạt dinh dưỡng. Bạn chọn gì?',
    options:[{k:'a',t:'Dồn cả vào Tết vì đây là mùa lớn nhất năm'},{k:'b',t:'Chia đều cho Tết, Trung thu và mùa thi'},
             {k:'c',t:'Chạy rải rác mỗi tháng một ít, không theo mùa nào'},{k:'d',t:'Dồn vào mùa thi, nơi sản phẩm có lý do và ít đối thủ'}],
    answer:'d', why:{a:'Lớn nhưng tiếng nói của bạn quá mỏng giữa hàng trăm hãng.',
      b:'Chia ba thì mỗi mùa chỉ 400 triệu, không mùa nào đủ đậm.',
      c:'Rải đều bỏ mất lợi thế nhu cầu dồn vào mùa.',
      d:'Đúng. Lý do thật (ôn thi) cộng với ít đối thủ làm tiền có hiệu quả.'} },
  { type:'calc', stem:'Năm hai hãng chi 0,8 tỉ, doanh thu tháng 6 vẫn cao hơn tháng 6 năm trước 0,9 tỉ, biên lợi nhuận gộp 40%. Lãi gộp tăng thêm trừ chi phí chiến dịch thì năm hai còn lỗ bao nhiêu tỉ?',
    unit:'tỉ', ans:0.44, tol:0.01, wrong:[[0.1,'HOAN_VON_TINH_DOANH_THU'],[0.36,'QUEN_TRU_CHI_PHI_QC']], errors:['HOAN_VON_TINH_DOANH_THU','QUEN_TRU_CHI_PHI_QC'],
    steps:['Lãi gộp tăng thêm = 0,9 × 40% = 0,36 tỉ.','Trừ chi phí chiến dịch: 0,36 − 0,8 = −0,44 tỉ, tức lỗ <b>0,44</b> tỉ.','Dù chi phí rẻ hơn, năm hai vẫn lỗ nếu chỉ tính tháng 6; chỉ nên tiếp khi còn lợi ích ngoài tháng 6 đo được, hoặc phải giảm chi phí mạnh hơn.'] },
  { type:'mcq', stem:'Năm đầu chi 1,2 tỉ, doanh thu tăng thêm 0,9 tỉ, biên gộp 40%. Trước khi chi tiếp năm hai, nên đặt tiêu chí nào?',
    options:[{k:'a',t:'Tiếp tục miễn là doanh số tháng 6 vẫn cao hơn các tháng thường khác'},{k:'b',t:'Tiếp tục nếu chi phí giảm rõ và lãi gộp thêm tiến gần mức hoà vốn'},
             {k:'c',t:'Bỏ ngay vì năm đầu đã lỗ, tức mùa thi không hợp sản phẩm'},{k:'d',t:'Chờ đến năm thứ năm vì thương hiệu cần nhiều năm để gắn vào mùa'}],
    answer:'b', why:{a:'Cao hơn tháng thường chưa chứng tỏ có lãi; mùa thi vốn đã đẩy doanh số, và chi phí chưa được tính.',
      b:'Đúng. Đặt ngưỡng trước: chi phí phải giảm và lãi gộp thêm phải tiến gần hoà vốn, nếu không thì chuyển ngân sách.',
      c:'Một năm lỗ là chi phí học, chưa đủ để kết luận; cần xem năm hai có cải thiện không.',
      d:'Chờ năm năm là cho phép lỗ kéo dài mà không có điểm dừng; năm hai đã cho tín hiệu.'} },
  { type:'mcq', stem:'Một hãng bút bi muốn gắn với mùa tựu trường. Điều gì cho thấy đây là cửa vào có lý do thật?',
    options:[{k:'a',t:'Phụ huynh mua đồ dùng học tập mới đúng dịp này hằng năm'},{k:'b',t:'Mùa tựu trường có nhiều ngày lễ để chạy khuyến mãi'},
             {k:'c',t:'Hãng có ngân sách dư vào tháng 8'},{k:'d',t:'Đối thủ lớn nhất ngành bút bi không quảng cáo gì trong tháng 8 năm ngoái'}],
    answer:'a', why:{a:'Đúng. Có hành vi mua thật gắn với khoảnh khắc đó.',
      b:'Ngày lễ không phải lý do dùng sản phẩm.',
      c:'Ngân sách dư là lý do của hãng, không phải của khách.',
      d:'Đối thủ vắng là độ trống, không phải lý do thật.'} },
  { type:'mcq', stem:'Vì sao chiếm một mùa rồi bỏ sau một năm là lãng phí?',
    options:[{k:'a',t:'Vì hợp đồng quảng cáo mùa vụ thường ký nhiều năm'},{k:'b',t:'Vì phải in lại bao bì theo mùa mới'},
             {k:'c',t:'Vì liên kết mới gắn được một năm sẽ phai và dễ bị đối thủ lấp'},{k:'d',t:'Vì khách sẽ nghĩ thương hiệu đã ngừng sản xuất và chuyển sang hãng khác'}],
    answer:'c', why:{a:'Không liên quan đến hợp đồng.',
      b:'Bao bì là chuyện phụ.',
      c:'Đúng. Một mùa mỗi năm chỉ gặp nhau vài tuần; bỏ một năm là mất gần hết.',
      d:'Suy luận quá xa; vấn đề là trí nhớ phai.'} },
  { type:'mcq', stem:'Hãng bút bi chạy chiến dịch tựu trường, tháng 8 doanh số tăng 40% so với tháng 7. Cách nào cho biết chiến dịch có công?',
    options:[{k:'a',t:'So với tháng 7 ngay trước đó, vì cùng năm và cùng điều kiện bán hàng'},{k:'b',t:'So với doanh số tháng 8 của đối thủ lớn nhất ngành'},
             {k:'c',t:'Xem lượt thích và bình luận của chiến dịch trong tháng 8'},{k:'d',t:'So với tháng 8 năm trước hoặc với vùng chưa chạy chiến dịch'}],
    answer:'d', why:{a:'Tháng 8 vốn đã là mùa mua đồ học tập, nên tăng so với tháng 7 có thể xảy ra dù không có chiến dịch.',
      b:'Đối thủ có quy mô và chiến dịch riêng; so sánh này không tách được phần tăng do mùa.',
      c:'Tương tác cho biết sự chú ý, không cho biết doanh số tăng nhờ đâu.',
      d:'Đúng. Cùng kỳ năm trước hay vùng đối chứng giữ yếu tố mùa vụ không đổi, phần chênh mới là công của chiến dịch.'} } ] },

/* ------------------------------------------------------------------ 06 */
{ id:'B:tp02-06', skill:'measure', read:'7 phút', t:'Đo thế nào để biết thương hiệu đã gắn được với cửa vào?',
  situation:'Sau 6 tháng chạy thông điệp "Giữa trưa nắng", sếp hỏi: "Có gắn được chưa?" Chỉ số nhận biết thương hiệu tăng từ 30% lên 34%, nhưng con số này không nói gì về tình huống. Bạn cần một cách đo khác trước buổi họp quý.',
  concept:{ name:'Câu hỏi gợi tình huống trong khảo sát',
    body:'Thay vì hỏi "Bạn có biết thương hiệu X không?", hãy đặt người trả lời vào tình huống: "Khi phải làm việc ngoài trời giữa trưa nắng, bạn nghĩ đến những loại nước nào?" Cho chọn nhiều thương hiệu. Tỉ lệ người nhắc tên bạn trong từng tình huống là <b>độ gắn thương hiệu – cửa vào</b>. Làm cùng bộ câu hỏi cho 5–10 tình huống, trước và sau chiến dịch, với cùng kiểu mẫu người trả lời. Cửa vào bạn đầu tư phải tăng rõ hơn các cửa vào khác; nếu mọi cửa vào tăng đều thì đó là tăng nhận biết chung, không phải gắn.' },
  example:'Khảo sát 500 người trước và sau. Ở tình huống "giữa trưa nắng", tỉ lệ nhắc đến thương hiệu tăng từ 8% lên 20%. Ở "sau buổi tập gym" — không đầu tư — từ 6% lên 7%. Chênh lệch này là bằng chứng chiến dịch gắn được vào đúng cửa vào đã chọn, dù chỉ số nhận biết chung chỉ tăng 4 điểm.',
  takeaway:'Đo độ gắn bằng cách đặt người trả lời vào tình huống, rồi so cửa vào đã đầu tư với cửa vào không đầu tư.',
  apply:'Viết một câu hỏi khảo sát bắt đầu bằng "Khi…" cho một cửa vào của sản phẩm quen, đọc to và kiểm tra nó có nhắc tên thương hiệu nào không.',
  mistakes:['Dùng chỉ số nhận biết chung để kết luận về một cửa vào cụ thể.','Đặt tên thương hiệu vào câu hỏi, khiến người trả lời bị gợi ý.'],
  q:[
  { type:'mcq', stem:'Đoán trước: câu hỏi khảo sát nào đo đúng độ gắn thương hiệu với cửa vào "giữa trưa nắng"?',
    options:[{k:'a',t:'"Bạn có biết nước điện giải [tên] không?"'},{k:'b',t:'"Bạn đánh giá [tên] bao nhiêu điểm trên thang 10?"'},
             {k:'c',t:'"Khi làm việc ngoài trời giữa trưa nắng, bạn nghĩ đến những loại nước nào?"'},{k:'d',t:'"Bạn có thích quảng cáo có người làm việc giữa trưa nắng không?"'}],
    answer:'c', why:{a:'Đo nhận biết chung, không gắn với tình huống.',
      b:'Đo thiện cảm, cũng không nói gì về tình huống.',
      c:'Đúng. Đặt vào tình huống, không gợi tên, để xem thương hiệu nào tự hiện ra.',
      d:'Đo độ thích quảng cáo, không đo trí nhớ.'} },
  { type:'mcq', stem:'Bạn có ngân sách cho một đợt khảo sát sau chiến dịch. Bạn chọn thiết kế nào để trả lời câu "gắn được chưa"?',
    options:[{k:'a',t:'Chỉ hỏi về cửa vào đã đầu tư, càng nhiều câu càng tốt'},{k:'b',t:'Hỏi cùng bộ tình huống như đợt trước, gồm cả cửa vào không đầu tư'},
             {k:'c',t:'Hỏi khách hàng trung thành qua fanpage để có câu trả lời nhanh'},{k:'d',t:'Đổi sang bộ tình huống mới hơn để có thêm góc nhìn khác mẻ'}],
    answer:'b', why:{a:'Không có cửa vào đối chứng thì không tách được tăng do chiến dịch hay tăng chung.',
      b:'Đúng. Cùng câu hỏi, có đối chứng, mới so được trước và sau.',
      c:'Mẫu fan đã thiên lệch, không đại diện cho người mua trong ngành.',
      d:'Đổi câu hỏi thì mất khả năng so sánh với đợt trước.'} },
  { type:'calc', stem:'Độ gắn ở "giữa trưa nắng" tăng từ 8% lên 20%. Mức tăng tính theo điểm phần trăm là bao nhiêu?',
    unit:'điểm %', ans:12, tol:0, wrong:[[150,'NHAM_DIEM_PHAN_TRAM']], errors:['NHAM_DIEM_PHAN_TRAM'],
    steps:['Điểm phần trăm = tỉ lệ sau − tỉ lệ trước.','20 − 8 = <b>12</b> điểm phần trăm (tương đương tăng 150% tương đối).'] },
  { type:'mcq', stem:'Cửa vào đã đầu tư tăng 12 điểm, cửa vào không đầu tư tăng 1 điểm. Kết luận nào vững nhất?',
    options:[{k:'a',t:'Chiến dịch làm tăng nhận biết chung ở các tình huống'},{k:'b',t:'Cần cắt đầu tư vì cửa vào khác không tăng mấy'},
             {k:'c',t:'Kết quả do mẫu khảo sát lần sau khác lần trước'},{k:'d',t:'Chiến dịch gắn được thương hiệu vào đúng tình huống đã chọn'}],
    answer:'d', why:{a:'Nếu tăng chung thì cửa vào đối chứng cũng tăng tương tự.',
      b:'Cửa vào khác không được đầu tư, không tăng là bình thường.',
      c:'Có thể là một khả năng, nhưng cùng một mẫu thì chênh 12 so với 1 khó giải thích bằng mẫu.',
      d:'Đúng. Chênh lệch giữa hai cửa vào là dấu vết của chiến dịch.'} },
  { type:'mcq', stem:'Vì sao không nên đặt tên thương hiệu trong câu hỏi tình huống?',
    options:[{k:'a',t:'Vì người trả lời sẽ được nhắc và chọn tên đó nhiều hơn thực tế'},{k:'b',t:'Vì bảng hỏi sẽ quá dài và người trả lời bỏ ngang giữa chừng'},
             {k:'c',t:'Vì đối thủ có thể xem được bảng hỏi'},{k:'d',t:'Vì làm vậy khiến khảo sát tốn thêm chi phí'}],
    answer:'a', why:{a:'Đúng. Gợi tên là đo độ nhận ra, không phải độ tự nhớ ra trong tình huống.',
      b:'Thêm một tên không làm bảng hỏi dài đáng kể.',
      c:'Không phải lý do chính.',
      d:'Chi phí không đổi.'} },
  { type:'mcq', stem:'Một chuỗi nhà thuốc muốn biết mình có gắn với "con sốt về đêm" không. Cách đo nào đúng tinh thần bài?',
    options:[{k:'a',t:'Đếm số đơn hàng lúc 22–24 giờ trong ba tháng qua'},{k:'b',t:'Hỏi phụ huynh: "Khi con sốt về đêm, bạn nghĩ đến mua thuốc ở đâu?"'},
             {k:'c',t:'Hỏi phụ huynh có hài lòng với nhà thuốc không'},{k:'d',t:'Xem lượt tương tác bài đăng về sốt ở trẻ nhỏ trên fanpage chuỗi nhà thuốc'}],
    answer:'b', why:{a:'Đơn hàng cho thấy kết quả, không tách được lý do là trí nhớ hay chỉ vì gần nhà.',
      b:'Đúng. Đặt vào tình huống và để họ tự nêu tên.',
      c:'Hài lòng là chuyện khác với việc nhớ ra lúc cần.',
      d:'Tương tác đo sự quan tâm đến nội dung, không đo trí nhớ.'} },
  { type:'mcq', stem:'Chỉ số nhận biết thương hiệu tăng 4 điểm, độ gắn ở cửa vào đã chọn tăng 12 điểm. Khi báo cáo sếp, nên nhấn điều gì?',
    options:[{k:'a',t:'Nhận biết chung tăng, đó là chỉ số sếp đã quen theo dõi'},{k:'b',t:'Cả hai chỉ số đều quan trọng ngang nhau nên đọc bằng nhau'},
             {k:'c',t:'Độ gắn tình huống tăng mạnh, vì đó là mục tiêu của thông điệp'},{k:'d',t:'Không nên báo cáo gì cho đến khi doanh số tháng này về đầy đủ'}],
    answer:'c', why:{a:'Quen thuộc nhưng không đo đúng mục tiêu đã đặt.',
      b:'Mục tiêu là gắn cửa vào, nên chỉ số đó là chính.',
      c:'Đúng. Báo cáo theo mục tiêu của chiến dịch, dùng nhận biết chung làm bối cảnh.',
      d:'Doanh số là quan trọng nhưng không thay cho bằng chứng về trí nhớ.'} } ] },

/* ------------------------------------------------------------------ 07 */
{ id:'B:tp02-07', skill:'brand', read:'7 phút', t:'Muốn tăng trưởng, nên mở thêm cửa vào nào?',
  situation:'Một thương hiệu sữa chua uống đã gắn chắc với "bữa sáng của trẻ". Doanh số đi ngang hai năm vì gần như mọi nhà có con nhỏ đã mua. Ban giám đốc muốn tăng 20% trong năm tới. Có ba hướng: giảm giá, ra vị mới, hoặc mở cửa vào mới.',
  concept:{ name:'Tăng trưởng bằng cửa vào kế cận',
    body:'Khi đã giữ chặt một cửa vào, thêm khách từ đúng cửa vào đó ngày càng khó. Một hướng tăng trưởng hợp lý, gần với tư duy "mental availability" của Ehrenberg-Bass, là <b>thêm tình huống mà người ta nghĩ đến bạn</b>: cùng khách nhưng dịp mới, hoặc khách mới ở dịp gần giống. Cửa vào kế cận tốt là cửa vào chia sẻ một phần khoảnh khắc, cảm giác hoặc người mua với cửa vào cũ, để thương hiệu không phải xây từ con số không. Mỗi cửa vào mới là thêm một lần mỗi tuần khách có thể nghĩ đến bạn.' },
  example:'Nhóm liệt kê cửa vào kế cận: "bữa xế khi con tan học" (cùng người mua là mẹ, cùng đứa trẻ), "người lớn ăn sáng vội" (cùng khoảnh khắc buổi sáng). Chọn "bữa xế tan học" vì cùng người mua. Nếu 30% trong số 1 triệu hộ đang mua thêm 2 chai mỗi tuần, lượng bán tăng 600 nghìn chai/tuần — trên nền 3 triệu chai, tức tăng 20%.',
  takeaway:'Khi cửa vào cũ đã đầy, tăng trưởng đến từ việc được nghĩ đến ở thêm một khoảnh khắc nữa.',
  apply:'Chọn một thương hiệu đã rất quen thuộc, đề xuất trong 60 giây một cửa vào kế cận và giải thích nó chia sẻ gì với cửa vào cũ.',
  mistakes:['Chọn cửa vào mới quá xa khiến thương hiệu không có lý do để có mặt.','Mở cửa vào mới mà bỏ bẵng cửa vào cũ đang nuôi doanh số.'],
  q:[
  { type:'mcq', stem:'Đoán trước: thương hiệu đã gắn chắc với một cửa vào, doanh số đi ngang. Hướng tăng trưởng bền nào hợp nhất?',
    options:[{k:'a',t:'Giảm giá sâu để khách hiện có mua thêm trong vài tháng'},{k:'b',t:'Mở thêm một cửa vào kế cận mà khách có thể nghĩ đến mình'},
             {k:'c',t:'Tăng tần suất quảng cáo về cửa vào cũ gấp đôi'},{k:'d',t:'Ra thật nhiều vị mới để làm khách tò mò và thử liên tục'}],
    answer:'b', why:{a:'Giảm giá kéo doanh số ngắn hạn và làm mỏng lãi.',
      b:'Đúng. Thêm tình huống là thêm lần mua, không cần giành khách từ cửa vào đã bão hoà.',
      c:'Cửa vào cũ đã gần đầy, nói to hơn không thêm được bao nhiêu.',
      d:'Vị mới có thể giúp phụ, nhưng không tạo thêm dịp dùng.'} },
  { type:'mcq', stem:'Hai ứng viên: "bữa xế khi con tan học" và "tiệc nướng cuối tuần của người lớn". Bạn chọn cái nào cho sữa chua uống?',
    options:[{k:'a',t:'Tiệc nướng, vì người lớn có sức mua cao hơn trẻ em'},{k:'b',t:'Cả hai, để tăng cơ hội đạt mục tiêu 20%'},
             {k:'c',t:'Bữa xế tan học, cùng người mua và cùng đứa trẻ với cửa vào cũ'},{k:'d',t:'Không chọn cái nào, đổi sang giảm giá vì nhanh ra kết quả hơn'}],
    answer:'c', why:{a:'Tiệc nướng quá xa: khác người mua, khác khoảnh khắc, sản phẩm không có lý do rõ.',
      b:'Làm cả hai chia mỏng ngân sách và làm rối hình ảnh.',
      c:'Đúng. Cửa vào kế cận chia sẻ người mua, nên dễ gắn nhất.',
      d:'Giảm giá không tạo tăng trưởng bền.'} },
  { type:'calc', stem:'Có 1 triệu hộ đang mua, mỗi tuần bán 3 triệu chai. Nếu 30% số hộ mua thêm 2 chai mỗi tuần cho bữa xế, lượng bán tăng bao nhiêu phần trăm?',
    unit:'%', ans:20, tol:0.1, wrong:[[66.7,'SAI_TINH_TOAN'],[10,'SAI_TINH_TOAN']], errors:['SAI_TINH_TOAN'],
    steps:['Số hộ mua thêm = 30% × 1.000.000 = 300.000 hộ.','Chai tăng thêm = 300.000 × 2 = 600.000 chai/tuần.','Tỉ lệ tăng = 600.000 ÷ 3.000.000 = <b>20%</b>.'] },
  { type:'mcq', stem:'Vì sao cửa vào mới nên "kế cận" cửa vào cũ?',
    options:[{k:'a',t:'Vì có thể dùng chung ngân sách mà không cần thêm tiền'},{k:'b',t:'Vì luật quảng cáo không cho đổi hẳn tình huống sử dụng'},
             {k:'c',t:'Vì đối thủ thường không để ý đến những cửa vào kế cận'},{k:'d',t:'Vì chia sẻ người mua hoặc khoảnh khắc nên dễ tin và dễ gắn'}],
    answer:'d', why:{a:'Vẫn cần thêm tiền; lợi ích là mỗi đồng đi xa hơn.',
      b:'Không có quy định như vậy.',
      c:'Đối thủ có thể để ý; lợi thế nằm ở điểm chung với trí nhớ sẵn có.',
      d:'Đúng. Khách thấy hợp lý ngay, không phải học lại thương hiệu là gì.'} },
  { type:'mcq', stem:'Một thương hiệu bánh quy gắn với "đãi khách ngày Tết" muốn tăng trưởng. Cửa vào kế cận hợp lý nhất là gì?',
    options:[{k:'a',t:'Quà mang đi khi thăm nhà người thân ngày thường'},{k:'b',t:'Đồ ăn cho người tập thể hình trước buổi tập nặng'},
             {k:'c',t:'Bữa sáng nhanh của sinh viên trước giờ lên lớp'},{k:'d',t:'Món ăn vặt khi xem bóng đá đêm khuya cùng bạn bè'}],
    answer:'a', why:{a:'Đúng. Cùng tinh thần mời, biếu, cùng người mua — chỉ mở rộng từ Tết ra quanh năm.',
      b:'Quá xa với hình ảnh bánh quy biếu tặng.',
      c:'Khác người mua và khác vai trò của sản phẩm.',
      d:'Có thể được, nhưng xa hơn nhiều so với "biếu khi thăm nhà".'} },
  { type:'mcq', stem:'Sau khi mở "bữa xế tan học", bạn nên làm gì với cửa vào "bữa sáng của trẻ"?',
    options:[{k:'a',t:'Dừng quảng cáo vì khách đã nhớ quá rõ rồi'},{k:'b',t:'Giữ đủ mức nhắc lại để không bị đối thủ lấn vào'},
             {k:'c',t:'Chuyển hết ngân sách sang cửa vào bữa xế'},{k:'d',t:'Đổi hẳn sang cửa vào mới để hình ảnh thương hiệu thống nhất hơn'}],
    answer:'b', why:{a:'Trí nhớ phai dần; dừng hẳn là mở cửa cho đối thủ.',
      b:'Đúng. Cửa vào cũ đang nuôi doanh số, cần duy trì ở mức vừa đủ.',
      c:'Dồn hết đi là đánh đổi doanh số chắc lấy doanh số chưa chắc.',
      d:'Hai cửa vào kế cận không mâu thuẫn nhau.'} },
  { type:'mcq', stem:'Dấu hiệu nào cho thấy một cửa vào mới đang bắt đầu có tác dụng?',
    options:[{k:'a',t:'Lượt thích bài đăng về bữa xế tăng gấp đôi'},{k:'b',t:'Doanh số buổi sáng tăng thêm 5% trong quý'},
             {k:'c',t:'Tỉ lệ người nhắc tên bạn trong tình huống "bữa xế" tăng rõ'},{k:'d',t:'Đối thủ bắt đầu ra sản phẩm và quảng cáo nói về bữa xế cho trẻ'}],
    answer:'c', why:{a:'Lượt thích không đo trí nhớ trong tình huống.',
      b:'Doanh số buổi sáng thuộc cửa vào cũ.',
      c:'Đúng. Đo độ gắn trong đúng tình huống mới.',
      d:'Đối thủ làm theo là tín hiệu thị trường, không đo trí nhớ của khách với bạn.'} } ] },

/* ------------------------------------------------------------------ 08 */
{ id:'B:tp02-08', skill:'insight', read:'7 phút', t:'Thương hiệu B2B thì cửa vào ngành hàng trông ra sao?',
  situation:'Bạn làm marketing cho một phần mềm kế toán cho doanh nghiệp nhỏ. Website toàn nói "tự động hoá", "báo cáo thông minh". Đội bán hàng kể: khách thường gọi đến vào những lúc rất cụ thể. Bạn muốn viết lại thông điệp theo đúng những lúc đó.',
  concept:{ name:'Cửa vào B2B: sự kiện kích hoạt trong doanh nghiệp',
    body:'Ở B2B, cửa vào thường là <b>một sự kiện khiến doanh nghiệp phải tìm giải pháp</b>: kế toán nghỉ việc, sắp đến hạn quyết toán, mở chi nhánh thứ hai, bị đối tác đòi hoá đơn nhanh hơn. Sự kiện có cái báo trước (dự định mở chi nhánh), có cái ập đến (kế toán nghỉ ngay tuần này): cái đầu cho thời gian so sánh nên thông điệp là chuẩn bị, cái sau cần lời giải ngay. Người nghĩ đến ngành hàng có thể là chủ doanh nghiệp, kế toán trưởng hay trợ lý, mỗi người gặp sự kiện khác nhau. Liệt kê theo vai trò, rồi gắn thương hiệu vào vài sự kiện phổ biến nhất và có mặt khi họ gõ tìm.' },
  example:'Đội bán hàng nhìn lại 80 cuộc gọi gần nhất: 28 cuộc sau khi kế toán nghỉ việc, 22 cuộc trước hạn quyết toán, 12 cuộc khi mở chi nhánh, còn lại rải rác. Nhưng đó chỉ là khách đã chọn gọi bạn, nên họ hỏi thêm 10 khách đã bỏ đi và 10 khách chọn đối thủ: nhiều người nhắc "bị đối tác đòi hoá đơn điện tử", sự kiện gần như vắng trong 80 cuộc gọi. Thông điệp mới: "Kế toán vừa nghỉ? Sổ sách vẫn chạy." Trang đích riêng hướng dẫn bàn giao dữ liệu trong một ngày.',
  takeaway:'Khách doanh nghiệp không mua phần mềm vì một ngày đẹp trời — họ mua khi một sự kiện buộc họ phải làm.',
  apply:'Chọn một dịch vụ B2B bạn biết, kể trong 60 giây ba sự kiện khiến doanh nghiệp bắt đầu tìm dịch vụ đó, mỗi sự kiện thuộc một vai trò khác nhau.',
  mistakes:['Nói về tính năng mà không nói đến sự kiện khiến khách cần.','Chỉ viết cho người dùng cuối, bỏ qua người ra quyết định gặp sự kiện khác.'],
  q:[
  { type:'mcq', stem:'Đoán trước: sự kiện nào khiến doanh nghiệp nhỏ nghĩ đến phần mềm kế toán SỚM nhất, khi chưa có khủng hoảng?',
    options:[{k:'a',t:'Còn ba ngày là hết hạn nộp hồ sơ quyết toán thuế'},{k:'b',t:'Chủ lên kế hoạch mở chi nhánh thứ hai vào quý sau'},
             {k:'c',t:'Kế toán báo nghỉ việc ngay trong tuần này'},{k:'d',t:'Đối tác yêu cầu xuất hoá đơn điện tử ngay hôm nay'}],
    answer:'b', why:{a:'Sát hạn là lúc đã hoảng; khách cần giải pháp kịp, không còn thời gian so sánh.',
      b:'Đúng. Kế hoạch báo trước hàng tháng, nên thông điệp có chỗ cho việc chuẩn bị và so sánh.',
      c:'Nghỉ việc ập đến và cần giải quyết trong vài ngày, là sự kiện muộn chứ không sớm.',
      d:'Đòi hỏi từ đối tác có hạn ngay trong ngày, khách chỉ muốn xử lý được ngay.'} },
  { type:'mcq', stem:'Bạn chỉ có ngân sách cho hai trang đích mới. Dựa trên 80 cuộc gọi, bạn làm gì?',
    options:[{k:'a',t:'Làm cho "kế toán nghỉ việc" và "trước hạn quyết toán"'},{k:'b',t:'Làm một trang chung về tính năng và một trang bảng giá'},
             {k:'c',t:'Làm cho "mở chi nhánh" vì đó là khách lớn nhất'},{k:'d',t:'Làm cho những sự kiện hiếm gặp vì ít đối thủ nói tới và dễ thắng hơn'}],
    answer:'a', why:{a:'Đúng. Hai sự kiện này chiếm 50/80 cuộc gọi.',
      b:'Trang tính năng không gặp khách ở đúng lúc họ cần.',
      c:'Khách lớn nhưng chỉ 12/80 cuộc gọi.',
      d:'Hiếm gặp thì không đủ lượng để đáng làm trang riêng khi chỉ có hai.'} },
  { type:'calc', stem:'Trong 80 cuộc gọi, 28 cuộc đến sau khi kế toán nghỉ việc. Tỉ lệ là bao nhiêu phần trăm?',
    unit:'%', ans:35, tol:0.1, wrong:[[285.7,'SAI_MAU_SO']], errors:['SAI_MAU_SO'],
    steps:['Tỉ lệ = 28 ÷ 80.','= 0,35 = <b>35%</b>.'] },
  { type:'mcq', stem:'Vì sao ở B2B cần liệt kê cửa vào theo từng vai trò?',
    options:[{k:'a',t:'Vì doanh nghiệp lớn yêu cầu hồ sơ năng lực riêng cho từng phòng ban'},{k:'b',t:'Vì mỗi vai trò gặp sự kiện khác nhau khiến họ nghĩ đến ngành hàng'},
             {k:'c',t:'Vì vai trò quyết định giá cuối cùng'},{k:'d',t:'Vì người dùng hằng ngày luôn là người duyệt chi cuối cùng'}],
    answer:'b', why:{a:'Hồ sơ năng lực là tài liệu bán hàng, không phải cửa vào.',
      b:'Đúng. Kế toán gặp hạn quyết toán, chủ doanh nghiệp gặp chuyện mở chi nhánh.',
      c:'Giá không phụ thuộc chủ yếu vào vai trò người tìm.',
      d:'Người dùng hằng ngày thường khác người duyệt chi; nhiều khi kế toán hay trợ lý tìm trước, chủ doanh nghiệp quyết sau.'} },
  { type:'mcq', stem:'Một công ty cho thuê văn phòng muốn viết thông điệp theo cửa vào. Câu nào đúng tinh thần bài?',
    options:[{k:'a',t:'"Văn phòng hiện đại, vị trí đắc địa, giá cạnh tranh"'},{k:'b',t:'"Không gian làm việc truyền cảm hứng cho đội ngũ sáng tạo"'},
             {k:'c',t:'"Đội vừa lên 20 người? Chuyển văn phòng trong một tuần"'},{k:'d',t:'"Hơn 500 doanh nghiệp đã tin tưởng lựa chọn chúng tôi"'}],
    answer:'c', why:{a:'Liệt kê thuộc tính, không có sự kiện nào.',
      b:'Lợi ích cảm xúc chung, không gắn với lúc doanh nghiệp cần chuyển.',
      c:'Đúng. Sự kiện kích hoạt cụ thể — đội lớn lên, văn phòng cũ chật.',
      d:'Bằng chứng xã hội, không nói tình huống.'} },
  { type:'mcq', stem:'Đội chỉ ghi lại lý do khách gọi đến bạn. Điểm yếu lớn nhất của nguồn này là gì và nên bổ sung gì?',
    options:[{k:'a',t:'Chỉ có khách đã chọn bạn; cần hỏi khách bỏ đi hoặc chọn đối thủ'},{k:'b',t:'Cuộc gọi ngắn nên thiếu chi tiết; cần ghi âm toàn bộ để nghe lại sau'},
             {k:'c',t:'Khách thường nói không đúng lý do; cần đối chiếu với hợp đồng đã ký'},{k:'d',t:'Mẫu 80 cuộc quá ít; cần ít nhất một nghìn cuộc trước khi dùng'}],
    answer:'a', why:{a:'Đúng. Cuộc gọi chỉ chứa người sống sót đến với bạn; sự kiện của khách chọn nơi khác không xuất hiện.',
      b:'Độ chi tiết là vấn đề phụ; thiên lệch về ai gọi mới làm méo bức tranh sự kiện.',
      c:'Lý do khách nêu thường vẫn dùng được; hợp đồng không ghi lúc khách bắt đầu tìm.',
      d:'80 cuộc đủ để lộ cụm sự kiện; ghi thêm cũng không sửa được việc thiếu tiếng nói của khách không gọi.'} },
  { type:'mcq', stem:'Phần mềm kế toán gắn được với "kế toán vừa nghỉ việc". Điều gì cần có để cửa vào này thành doanh số?',
    options:[{k:'a',t:'Đăng đều mỗi tháng một bài mạng xã hội về chuyện tuyển và giữ chân nhân sự kế toán'},{k:'b',t:'Giảm giá sâu cho khách mới để cạnh tranh với đối thủ'},
             {k:'c',t:'Thêm nhiều tính năng để hơn đối thủ trên giấy'},{k:'d',t:'Khi khách tìm, họ thấy ngay cách chuyển giao sổ sách trong một ngày'}],
    answer:'d', why:{a:'Nói về nhân sự chung chung không đáp đúng nỗi lo lúc đó.',
      b:'Giảm giá không giải quyết nỗi lo cấp bách của khách.',
      c:'Nhiều tính năng không trả lời "làm sao chạy tiếp ngay bây giờ".',
      d:'Đúng. Gắn được rồi thì phải có mặt khi khách tìm và giải đúng nỗi lo của sự kiện.'} } ] },

/* ------------------------------------------------------------------ 09 */
{ id:'B:tp02-09', skill:'creative', read:'6 phút', t:'Quảng cáo chỉ nói lợi ích, không nói tình huống — sai ở đâu?',
  situation:'Bạn duyệt năm mẫu quảng cáo cho một hãng ổ cắm điện thông minh. Cả năm mẫu đều có câu chính là "Tiết kiệm điện, an toàn, điều khiển bằng điện thoại". Đội thiết kế hỏi: "Lợi ích rõ vậy rồi, còn thiếu gì?"',
  concept:{ name:'Lợi ích cần một tình huống để được nhớ lại',
    body:'Lợi ích cho khán giả biết sản phẩm tốt ở đâu, nhưng không cho họ biết <b>khi nào nên nghĩ đến nó</b>. Không có tình huống, trí nhớ không có móc để treo thương hiệu — lần sau gặp đúng lúc cần, người ta không nhớ ra. Cách sửa: đặt lợi ích vào một khoảnh khắc cụ thể mà sản phẩm giải quyết thật. "Điều khiển bằng điện thoại" trở thành "Ra khỏi nhà mới nhớ quên tắt bàn là? Tắt từ điện thoại." Cái giá: một tình huống chỉ chạm một nhóm người, nên cần vài mẫu, mỗi mẫu một khoảnh khắc.' },
  example:'Nhóm sửa ba mẫu: "Ra khỏi nhà mới nhớ quên tắt bàn là?", "Đi du lịch cả tuần, bình nóng lạnh vẫn đang cắm?", "Con ngủ rồi, tắt đèn phòng mà không cần bước vào". Thử trên 300 người: mẫu có tình huống được nhớ lại tên thương hiệu 26%, mẫu chỉ lợi ích 14%. Ba lợi ích cũ vẫn xuất hiện, chỉ ở dòng phụ.',
  takeaway:'Lợi ích nói sản phẩm tốt ra sao; tình huống nói lúc nào cần nhớ ra nó — quảng cáo cần cả hai.',
  apply:'Lấy một câu quảng cáo toàn lợi ích, viết lại thành ba câu cho ba tình huống khác nhau, mỗi câu mở đầu bằng "Khi…" hoặc một câu hỏi, đọc to trong 60 giây.',
  mistakes:['Tưởng liệt kê nhiều lợi ích thì khách sẽ tự biết lúc nào cần.','Thêm tình huống nhưng quá chung như "trong cuộc sống hằng ngày".'],
  q:[
  { type:'mcq', stem:'Đoán trước: điều gì thiếu ở câu "Tiết kiệm điện, an toàn, điều khiển bằng điện thoại"?',
    options:[{k:'a',t:'Một khoảnh khắc cụ thể để khán giả biết lúc nào nghĩ đến sản phẩm'},{k:'b',t:'Thêm lợi ích thứ tư để thuyết phục hơn'},
             {k:'c',t:'Con số cụ thể về lượng điện tiết kiệm được mỗi tháng'},{k:'d',t:'Một người nổi tiếng đứng ra nói câu này cho đáng tin hơn hẳn'}],
    answer:'a', why:{a:'Đúng. Lợi ích đủ rồi; thiếu cái móc để trí nhớ gọi ra.',
      b:'Thêm lợi ích càng làm câu dài và khó nhớ.',
      c:'Con số làm lợi ích rõ hơn nhưng vẫn không có tình huống.',
      d:'Người nổi tiếng thu hút chú ý, không thay được tình huống.'} },
  { type:'mcq', stem:'Đội thiết kế hỏi "còn thiếu gì?". Bạn yêu cầu sửa gì?',
    options:[{k:'a',t:'Bỏ hết lợi ích, chỉ giữ tình huống để tối giản'},{k:'b',t:'Giữ nguyên câu, chỉ làm hình ảnh nổi bật hơn'},
             {k:'c',t:'Đưa một tình huống cụ thể lên câu chính, lợi ích xuống dòng phụ'},{k:'d',t:'Thêm dòng chữ "dùng được trong nhiều tình huống hằng ngày"'}],
    answer:'c', why:{a:'Bỏ hết lợi ích thì khán giả không biết vì sao nên chọn.',
      b:'Hình ảnh đẹp không bù được việc thiếu tình huống.',
      c:'Đúng. Tình huống làm móc, lợi ích làm lý do.',
      d:'Nhiều tình huống chung chung là không có tình huống nào.'} },
  { type:'calc', stem:'Mỗi mẫu chạy với 15,6 triệu đồng cho 300 người; mẫu tình huống có 78 người nhớ tên, mẫu chỉ lợi ích có 42. Chi phí cho mỗi người nhớ tên của mẫu lợi ích đắt hơn mẫu tình huống bao nhiêu nghìn đồng?',
    unit:'nghìn đồng', ans:171.4, tol:0.5, wrong:[[371.4,'SAI_TINH_TOAN'],[1300,'NHAM_DIEM_PHAN_TRAM']], errors:['SAI_TINH_TOAN','NHAM_DIEM_PHAN_TRAM'],
    steps:['Mẫu tình huống: 15 600 nghìn ÷ 78 = 200 nghìn đồng mỗi người.','Mẫu lợi ích: 15 600 nghìn ÷ 42 ≈ 371,4 nghìn đồng mỗi người.','Chênh lệch = 371,4 − 200 = <b>171,4</b> nghìn đồng.'] },
  { type:'mcq', stem:'Bốn câu dưới đều có khoảnh khắc. Câu nào đã sửa đúng lỗi "chỉ nói lợi ích" cho ổ cắm thông minh?',
    options:[{k:'a',t:'"Tối chủ nhật cả nhà xem phim, ngồi quây quần bên chiếc ổ cắm"'},{k:'b',t:'"Cuối tháng hoá đơn điện vọt lên? Xem ổ cắm nào ngốn điện nhất"'},
             {k:'c',t:'"Sáng nào cũng vội đi làm? Cuộc sống thông minh hơn mỗi ngày"'},{k:'d',t:'"Mùa nóng đến, điều hoà bật cả đêm trong căn phòng nhỏ"'}],
    answer:'b', why:{a:'Có cảnh cụ thể nhưng sản phẩm không giải quyết gì trong cảnh đó, nên khoảnh khắc không gọi ra thương hiệu.',
      b:'Đúng. Khoảnh khắc là lúc khách thấy hoá đơn, và lợi ích tiết kiệm điện là lời giải đúng lúc đó.',
      c:'"Sáng nào cũng" nghe cụ thể nhưng quá chung, và lợi ích "thông minh hơn" không đáp vào vấn đề nào.',
      d:'Có cảnh cụ thể và gần chủ đề điện, nhưng không nối với việc ổ cắm làm được; khách không biết phải nghĩ đến sản phẩm.'} },
  { type:'mcq', stem:'Một hãng bảo hiểm sức khoẻ viết: "Quyền lợi rộng, phí hợp lý, bồi thường nhanh". Tình huống nào nên thêm vào?',
    options:[{k:'a',t:'"Sinh nhật con, cả nhà chụp ảnh bên chiếc bánh kem to"'},{k:'b',t:'"Đứng chờ ở quầy làm thủ tục, tay cầm số thứ tự"'},
             {k:'c',t:'"Đọc tin dịch bệnh tăng, bỗng thấy lo lo trong lòng"'},{k:'d',t:'"Con sốt cao nửa đêm phải nhập viện — không lo viện phí"'}],
    answer:'d', why:{a:'Một khoảnh khắc ấm áp có thật nhưng không liên quan đến lúc cần bảo hiểm.',
      b:'Đây là bước thủ tục sau khi đã mua; không phải lúc người ta nghĩ đến bảo hiểm.',
      c:'Nỗi lo mơ hồ, chưa có cảnh nào để trí nhớ bám vào, và sản phẩm chưa là lời giải của cảnh nào.',
      d:'Đúng. Khoảnh khắc cụ thể mà phụ huynh nhận ra ngay, và quyền lợi giải trực tiếp nỗi lo đó.'} },
  { type:'mcq', stem:'Mẫu "quên tắt bàn là" chỉ chạm người hay ủi đồ. Hãng lo mất phần khách còn lại. Cách xử lý hợp lý nhất là gì?',
    options:[{k:'a',t:'Chạy nhiều mẫu song song, mỗi mẫu một tình huống cho một nhóm'},{k:'b',t:'Gộp ba tình huống vào một mẫu để khán giả tự chọn cái hợp'},
             {k:'c',t:'Quay lại câu chung "trong cuộc sống hằng ngày" cho ai cũng thấy'},{k:'d',t:'Chọn tình huống phổ biến nhất rồi mua thật nhiều lượt hiển thị'}],
    answer:'a', why:{a:'Đúng. Mỗi tình huống chạm một nhóm; nhiều mẫu giữ được độ cụ thể mà vẫn phủ được nhiều người.',
      b:'Ba khoảnh khắc nhồi vào một mẫu thì không cái nào đủ rõ để làm móc.',
      c:'Quay lại câu chung là bỏ độ cụ thể, tức bỏ đúng điều làm quảng cáo được nhớ lại.',
      d:'Nhiều lượt hiển thị cho một tình huống không tạo thêm móc cho nhóm khách ở tình huống khác.'} },
  { type:'mcq', stem:'Thử A/B: mẫu tình huống nhớ tên 26%, mẫu chỉ lợi ích 14%, nhưng tỉ lệ nhấp mua của hai mẫu bằng nhau. Kết luận hợp lý?',
    options:[{k:'a',t:'Mẫu tình huống thất bại, vì lượt nhấp mua không hơn mẫu chỉ lợi ích'},{k:'b',t:'Hai mẫu như nhau vì cùng tỉ lệ nhấp, nên chọn mẫu rẻ hơn để chạy'},
             {k:'c',t:'Tình huống giúp nhớ tên; tác dụng lên mua phải đo lúc có nhu cầu thật'},{k:'d',t:'Tỉ lệ nhớ tên 26% là quá thấp nên cả hai mẫu đều nên bỏ đi hết'}],
    answer:'c', why:{a:'Lượt nhấp lúc xem quảng cáo không phải lúc khách có nhu cầu; chưa đủ để gọi là thất bại.',
      b:'Hai mẫu khác nhau rõ ở nhớ tên; chỉ nhìn tỉ lệ nhấp là bỏ qua đúng thứ tình huống tạo ra.',
      c:'Đúng. Tình huống tác động lên việc nhớ lại khi nhu cầu xuất hiện; cần đo lúc đó, không đo qua cú nhấp tại chỗ.',
      d:'Không có chuẩn tuyệt đối; cần so với mẫu còn lại, và mẫu tình huống gần gấp đôi.'} } ] }

]});
